void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
  // Clear the bucket with label minLabel
  bucketsByLabel.get(minLabel).clear();

  // Loop through all labels and move vertices to the bucket with label 0
  for (int label : labels) {
    if (label != minLabel) {
      for (int vertex : bucketsByLabel.get(label)) {
        bucketsByLabel.get(0).add(vertex);
      }
      bucketsByLabel.get(label).clear();
    }
  }

  // Update the labeling by shifting all labels down
  for (int i = minLabel; i >= 0; i--) {
    if (i > 0) {
      bucketsByLabel.set(i, bucketsByLabel.get(i - 1));
      bucketsByLabel.set(i - 1, new HashSet<>());
    }
  }
}

